// Guided practice uses real game actions; progress belongs to the saved character.
const LESSONS=[
 ['move','まずは歩いてみよう','左スティックで移動。右スティックは照準です。少し歩くと次へ進みます。','WASD、矢印キー、または地面を左クリックして移動。'],
 ['attack','通常攻撃を出す','{attack}で剣撃。右スティックで狙えます。敵がいなくても練習できます。','Shift＋左クリックでその場攻撃。敵を左クリックすると追跡して攻撃。'],
 ['skill1','第1スキルを使う','{skill1}で第1スキル。初期装備は炎の弾。右スティックで狙い、長押しで繰り返します。','Q または右クリック。長押しで繰り返し発動。'],
 ['skill2','第2スキルを使う','{skill2}で第2スキル。初期装備は周囲への氷の輪。マナと再使用待ち時間が必要です。','Eで第2スキル。画面下の青い球がマナです。'],
 ['dash','回避を試そう','左スティックで方向を入れて{dash}。短く素早く移動します。壁は通り抜けられません。','Spaceで瞬歩。WASDで方向を指定できます。'],
 ['inventory','装備画面を開く','{inventory}で装備画面を開きます。左の装備・鞄アイコンを選ぶと、右に性能と操作が表示されます。','Iで装備画面。画面上の「装備」からも開けます。'],
 ['equip','鞄の防具を装備する','ZRで鞄へ移動（十字キーでも移動できます）。品を選び{accept} →「装備」を選び{accept}。{back}で一段戻ります。','左の鞄アイコンを選び、右の「装備」をクリック。矢印で選択 → Enterで操作へ → Enterで決定も可能。'],
 ['gems','スキルジェム画面を開く','装備交換で外れたジェムは元の装備に残ります。{back}で装備を閉じ、十字キー↑でジェム画面へ。','Gでジェム画面。装備画面の「スキルジェム」タブでも開けます。'],
 ['socket','ジェムをソケットに入れる','L/Rで画面切替。ジェム画面は十字キーで項目を移動し{accept}で決定。左の青いジェムを選択 → 右の「このジェムを装着する」 → 同じ色のソケットの順に決定します。','左の灰炎弾・霜の環などを選択 → 右の「このジェムを装着する」 → 同じ色のソケットをクリック。白はどの色でも可。'],
 ['bind','使うスキルを割り当てる','左の6つのスキル枠（Q/E/R/T/Y/U）から選び、右の選択欄へ{accept}で移動。装着したアクティブジェムを選びます。','Q/E/R/T/Y/Uの6枠に割り当てます。プロコンはY・X、ZL＋Y/X/A/Bで使い分けます。'],
 ['finish','探索の準備ができた','{back}で画面を閉じて探索へ。{interact}で拾う・調べる、{flask}で生命瓶、十字キー↓で成長。村のギルドで最初の討伐依頼を受け、草牙狼を8体倒して報告しよう。','Fで拾う・調べる、1で生命瓶、Pで成長、Tabで地図。村で依頼を受け、討伐後は村へ戻って報告。']
];
let tutorialGuideOpen=false,tutorialGuidePage=0,tutorialDistance=0,tutorialUIKey='';
function tutorialState(){return p?.tutorial||{step:0,active:false}}
function tutorialButton(action){let defaults={attack:'ZR',skill1:'Y',skill2:'X',dash:'B',inventory:'L',accept:'A',back:'B',interact:'A',flask:'R'};return padProfile.buttons[action]===PAD_DEFAULT[action]?defaults[action]:'Button '+padProfile.buttons[action]}
function tutorialText(text){return text.replace(/\{(\w+)\}/g,(_,key)=>tutorialButton(key))}
function tutorialEvent(event){let s=tutorialState();if(!s.active||LESSONS[s.step]?.[0]!==event)return;s.step++;tutorialDistance=0;tutorialUIKey='';save();playSound('ui');tutorialRender();if(LESSONS[s.step]?.[0]==='finish')tutorialShow(s.step)}
function tutorialStart(){if(!started){tutorialWelcomeBack();return}let s=p.tutorial||(p.tutorial={step:0});if(s.step>=LESSONS.length-1)s.step=0;s.active=true;
 if(!p.tutorialGearGiven&&p.bag.length<20){p.bag.push({slot:'armor',name:'練習用の胸甲',value:Math.max(3,p.armor?.value||3),color:'',rarity:'normal',mods:[],sockets:[{color:'B',gem:null},{color:'B',gem:null},{color:'R',gem:null}],links:[true,true]});p.tutorialGearGiven=true}
 tutorialDistance=0;tutorialGuideOpen=false;tutorialUIKey='';closePanel();save();tutorialRender()}
function tutorialStop(complete=false){if(p?.tutorial){p.tutorial.active=false;if(complete)p.tutorial.step=LESSONS.length-1;save()}tutorialGuideOpen=false;tutorialUIKey='';closePanel();tutorialRender()}
function tutorialSkip(){let s=tutorialState();if(!s.active)return;s.step=Math.min(LESSONS.length-1,s.step+1);save();tutorialShow(s.step)}
function tutorialWelcomeBack(){if(tutorialState().active&&tutorialState().step===LESSONS.length-1){tutorialStop(true);return}tutorialGuideOpen=false;if(started)closePanel();else{$('card').classList.remove('wide');welcome()}tutorialRender()}
function tutorialShow(page){tutorialGuidePage=clamp(page??tutorialState().step,0,LESSONS.length-1);tutorialGuideOpen=true;inventoryNav.open=false;padSettingsOpen=false;padCursor.active=false;paused=true;keys={};held=false;leftDown=false;rightDown=false;route=[];let lesson=LESSONS[tutorialGuidePage],s=tutorialState();$('modal').classList.remove('hidden');$('card').classList.add('wide');$('card').innerHTML='<label>FIRST STEPS / 操作チュートリアル</label><h2>'+lesson[1]+'</h2><div class="tutorial-progress">'+LESSONS.map((l,i)=>'<button class="'+(i===tutorialGuidePage?'current':'')+'" onclick="tutorialShow('+i+')" aria-label="'+(i+1)+' '+l[1]+'">'+(i+1)+'</button>').join('')+'</div><div class="tutorial-columns"><section><h3>🎮 プロコン</h3><p>'+tutorialText(lesson[2])+'</p></section><section><h3>キーボード・マウス</h3><p>'+lesson[3]+'</p></section></div><p class="tutorial-note">'+(tutorialGuidePage===6?'交換した装備は鞄に戻ります。ジェムは元の装備に残るため、新しい装備には装着し直してください。売却した品は戻せません。':tutorialGuidePage===8?'赤 R・緑 G・青 B がソケット色。サポートジェムは単独では使えず、線でつながった対応スキルを強化します。':tutorialGuidePage===9?'選択欄には装備中のアクティブジェムだけが表示されます。使えないときは装着・割り当て・マナ・待ち時間を確認。':'実践練習中は被ダメージなし。実際の装備変更やジェム操作は保存されます。練習用防具は一度だけ鞄に追加します。')+'</p><div class="tutorial-buttons"><button onclick="tutorialShow('+Math.max(0,tutorialGuidePage-1)+')" '+(!tutorialGuidePage?'disabled':'')+'>前の説明</button><button onclick="tutorialShow('+Math.min(LESSONS.length-1,tutorialGuidePage+1)+')" '+(tutorialGuidePage===LESSONS.length-1?'disabled':'')+'>次の説明</button><button id="tutorialPrimary" onclick="'+(s.active&&s.step===LESSONS.length-1?'tutorialStop(true)':started?'tutorialStart()':'tutorialWelcomeBack();showClassSelection()')+'">'+(s.active&&s.step===LESSONS.length-1?'練習を終えて探索へ':started?(s.active?'実践練習に戻る':'実践練習を始める'):'クラス選択へ（選択後に練習開始）')+'</button><button onclick="'+(s.active?'tutorialStop()':'tutorialWelcomeBack()')+'">'+(s.active?'練習を中断':'閉じる')+'</button>'+(s.active&&s.step<LESSONS.length-1?'<button onclick="tutorialSkip()">今の課題をスキップ</button>':'')+'</div><p class="muted">十字キーでボタンを選択 · '+tutorialButton('accept')+'で決定 · '+tutorialButton('back')+'で閉じる。上の番号や「前の説明」「次の説明」で見返せます。</p>';$('tutorialPrimary').focus();tutorialRender()}
function tutorialMarkup(){let s=tutorialState(),l=LESSONS[s.step];return '<b>練習 '+(s.step+1)+' / '+LESSONS.length+' · '+l[1]+'</b><p>'+tutorialText(l[2])+'</p><small>'+l[3]+'</small><div><button onclick="tutorialShow()">詳しい説明</button><button onclick="tutorialStop()">練習を中断</button></div>'}
function tutorialRender(){let s=tutorialState(),active=started&&s.active&&!dead&&!tutorialGuideOpen;let hud=$('tutorialHud');hud.hidden=!active||paused;let inline=$('tutorialInline');if(!active||!paused){if(inline)inline.remove()}else if(!inline){$('card').insertAdjacentHTML('afterbegin','<aside id="tutorialInline" class="tutorial-instruction"></aside>');inline=$('tutorialInline')}let key=[active,paused,s.step,padDevice?.id,JSON.stringify(padProfile.buttons)].join('|');if(key!==tutorialUIKey||inline&&!inline.innerHTML){if(active){hud.innerHTML=tutorialMarkup();if(inline)inline.innerHTML=tutorialMarkup()}tutorialUIKey=key}}
document.body.insertAdjacentHTML('beforeend','<aside id="tutorialHud" class="tutorial-instruction" hidden></aside>');document.querySelector('.menu').insertAdjacentHTML('beforeend','<button onclick="tutorialShow()">チュートリアル</button>');
const tutorialPanelBase=panel;panel=kind=>{tutorialGuideOpen=false;tutorialPanelBase(kind);if(kind==='inventory')tutorialEvent('inventory');if(kind==='gems')tutorialEvent('gems');tutorialUIKey='';tutorialRender();if(kind==='help'||kind==='pause')$('card').insertAdjacentHTML('beforeend','<button onclick="tutorialShow()">操作チュートリアルを開く</button>')};
const tutorialCloseBase=closePanel;closePanel=()=>{if(tutorialGuideOpen&&tutorialState().active&&tutorialState().step===LESSONS.length-1){p.tutorial.active=false;save()}if(tutorialGuideOpen&&!started){tutorialWelcomeBack();return}tutorialGuideOpen=false;tutorialCloseBase();tutorialUIKey='';tutorialRender()};
const tutorialNewBase=newGame;newGame=type=>{tutorialNewBase(type);p.tutorial={step:0,active:false};save();tutorialShow(0)};
const tutorialResumeBase=resume;resume=()=>{tutorialResumeBase();if(started&&tutorialState().active)tutorialShow()};
const tutorialWelcomeBase=welcome;welcome=()=>{tutorialWelcomeBase();$('card').insertAdjacentHTML('beforeend','<button onclick="tutorialShow(0)">はじめての方へ · 操作チュートリアル</button>')};
const tutorialEquipBase=equip;equip=i=>{if(!p.bag[i])return;if(tutorialEquipBase(i)===false)return false;tutorialEvent('equip');return true};
const tutorialSocketBase=socketGem;socketGem=(slot,i)=>{let before=p[slot]?.sockets[i]?.gem;tutorialSocketBase(slot,i);if(p[slot]?.sockets[i]?.gem&&p[slot].sockets[i].gem!==before)tutorialEvent('socket')};
const tutorialBindBase=bindSkill;bindSkill=(i,type)=>{tutorialBindBase(i,type);if(type&&skillBuild(type))tutorialEvent('bind');if(!tutorialGuideOpen)document.querySelectorAll('.bindings select')[i]?.focus()};
const tutorialCastBase=cast;cast=n=>{let before=playerAction,cool=cd[n];tutorialCastBase(n);if((playerAction&&playerAction!==before)||cd[n]>cool)tutorialEvent(['attack','skill1','skill2','dash'][n])};
const tutorialHurtBase=hurt;hurt=d=>{if(!tutorialState().active)tutorialHurtBase(d)};
const tutorialUpdateBase=update;update=dt=>{let before=started?{x:p.x,y:p.y}:null;tutorialUpdateBase(dt);let s=tutorialState();if(before&&s.active&&!paused&&!dead&&s.step===0){tutorialDistance+=Math.hypot(p.x-before.x,p.y-before.y);if(tutorialDistance>110)tutorialEvent('move')}tutorialRender()};
const tutorialMenuBase=padMenu;padMenu=(g,left,right,dt)=>{if(!tutorialGuideOpen){tutorialMenuBase(g,left,right,dt);return}if(padEdge(g,'back')||padEdge(g,'pause')){tutorialWelcomeBack();return}tutorialMenuBase(g,left,right,dt)};
if(!started)welcome();

const tutorialChooseBase=chooseGem;chooseGem=i=>{tutorialChooseBase(i);document.querySelectorAll('.gemcard')[i]?.focus()};

